import React, { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';

const ChatContext = createContext();

const dummyChannels = [
  { id: 'general', name: 'General' },
  { id: 'tech', name: 'Technology' },
  { id: 'sports', name: 'Sports' },
  { id: 'world', name: 'World News' }
];

export const ChatProvider = ({ children }) => {
  const { user } = useAuth();
  const [channels, setChannels] = useState([]);
  const [currentChannel, setCurrentChannel] = useState(null);
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    if (user) {
      // initialize channels when user logs in
      setChannels(dummyChannels);
    }
  }, [user]);

  const joinChannel = (channelId) => {
    setCurrentChannel(channelId);
    // load previous mock messages (empty for now)
    setMessages([]);
  };

  const sendMessage = (content) => {
    if (currentChannel) {
      const msg = {
        user,
        content,
        timestamp: new Date().toISOString(),
        channel: currentChannel
      };
      setMessages(prev => [...prev, msg]);
    }
  };

  return (
    <ChatContext.Provider value={{ channels, currentChannel, messages, joinChannel, sendMessage }}>
      {children}
    </ChatContext.Provider>
  );
};

export const useChat = () => useContext(ChatContext);
